export function buildDefaultDesktopConfig(data) {
  const dark = data.darkMode !== false;
  const corner = data.adaptation?.layout?.cornerStyle || "rounded";
  const nav = data.adaptation?.layout?.navigationStyle || "tabs";

  let pr = 10, cr = 8, cap = "10px";
  if (corner === "pill") { pr = 18; cr = 999; cap = "999px"; }
  else if (corner === "sharp") { pr = 0; cr = 0; cap = "0px"; }

  return {
    windowChrome: {
      titleBarHeight: 26,
      headerStyle: nav === "rail" ? "lcars-elbow" : "standard",
      cornerStyle: corner,
      panelRadius: pr,
      controlRadius: cr,
      borderWidth: 1,
      shadow: dark ? "0 14px 36px rgba(0,0,0,0.5)" : "0 10px 26px rgba(0,0,0,0.2)"
    },
    menuBar: {
      height: 28,
      fontSize: 11,
      letterSpacing: "0.06em",
      textTransform: dark ? "uppercase" : "none",
      dropdownRadius: pr,
      dropdownShadow: dark ? "0 12px 28px rgba(0,0,0,0.4)" : "0 8px 20px rgba(0,0,0,0.18)"
    },
    taskbar: {
      height: 40,
      buttonRadius: cr,
      dockAlignment: "left",
      quickChatBorderRadius: cr
    },
    cameraHud: {
      panelRadius: pr,
      buttonRadius: cr,
      shadow: "0 8px 20px rgba(0,0,0,0.3)"
    },
    sweep: {
      elbowWidth: 30,
      titleCapRadius: cap,
      accentBand: "primary",
      showElbowBar: true
    }
  };
}
